mapper.select:
WITH menu_tree AS ( SELECT m.menu_id, m.menu_code, m.parent_menu_id, m.menu_nm, m.menu_order, RIGHT(REPLICATE('0', 5) + CAST(ISNULL(m.menu_order, 0) AS varchar(5)), 5) AS sort_path, 1 AS depth FROM tb_menu m WHERE m.parent_menu_id IS NULL
UNION ALL
SELECT c.menu_id, c.menu_code, c.parent_menu_id, c.menu_nm, c.menu_order, mt.sort_path + '-' + RIGHT(REPLICATE('0', 5) + CAST(ISNULL(c.menu_order, 0) AS varchar(5)), 5) AS sort_path, mt.depth + 1 FROM tb_menu c INNER JOIN menu_tree mt ON c.parent_menu_id = mt.menu_id ) SELECT rmp.role_menu_permission_id AS roleMenuPermissionId, rmp.role_id AS roleId, r.role_code AS roleCode, rmp.menu_id AS menuId, m.menu_code AS menuCode, rmp.permission_id AS permissionId, p.permission_code AS permissionCode, 'Y' AS useAt, rmp.created_at AS frstRegistPnttm, 'SYSTEM' AS frstRegisterId, rmp.created_at AS lastUpdtPnttm, 'SYSTEM' AS lastUpdusrId, r.role_nm AS roleNm, mt.menu_nm AS menuNm, m.menu_url AS menuUrl, p.permission_nm AS permissionNm, CASE WHEN p.permission_code = 'PERM_WRITE' THEN 'write' ELSE 'read' END AS permissionLevel FROM tb_role_menu_permission rmp LEFT JOIN tb_role r ON rmp.role_id = r.role_id LEFT JOIN menu_tree mt ON rmp.menu_id = mt.menu_id LEFT JOIN tb_menu m ON rmp.menu_id = m.menu_id LEFT JOIN tb_permission p ON rmp.permission_id = p.permission_id WHERE 1 = 1
AND r.role_id = #{roleId}
AND r.role_code = #{roleCode}
AND m.menu_code = #{menuCode}
AND p.permission_code = #{permissionCode}
ORDER BY mt.sort_path

mapper.insert:
INSERT INTO tb_role_menu_permission (
    role_id,
    menu_id,
    permission_id,
    created_at
) VALUES (


            (
                SELECT TOP 1 r.role_id
                FROM tb_role r
                WHERE r.role_id = #{roleId}
                ORDER BY r.role_id
            )


            (
                SELECT TOP 1 r.role_id
                FROM tb_role r
                WHERE r.role_code = #{roleCode}
                ORDER BY r.role_id
            )

    ,
    (
        SELECT TOP 1 m.menu_id
        FROM tb_menu m
        WHERE m.menu_code = #{menuCode}
        ORDER BY m.menu_id
    ),


            (
                SELECT TOP 1 p.permission_id
                FROM tb_permission p
                INNER JOIN tb_role r ON r.tenant_id = p.tenant_id
                WHERE r.role_id = #{roleId}
                  AND p.permission_code = #{permissionCode}
                ORDER BY p.permission_id
            )


            (
                SELECT TOP 1 p.permission_id
                FROM tb_permission p
                INNER JOIN tb_role r ON r.tenant_id = p.tenant_id
                WHERE r.role_code = #{roleCode}
                  AND p.permission_code = #{permissionCode}
                ORDER BY p.permission_id
            )

    ,
    GETDATE()
)
